import{z as o,x as i,o as e,c as s,q as t,j as n,D as E,d as A,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"数据耗尽与再配比","description":"","frontmatter":{"title":"数据耗尽与再配比","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-data-exhaustion.md","filePath":"llm/pf2-data-exhaustion.md","lastUpdated":1791063341000}'),D={name:"llm/pf2-data-exhaustion.md"};function d(p,a,h,m,c,C){const B=i("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="数据耗尽与再配比" tabindex="-1">数据耗尽与再配比 <a class="header-anchor" href="#数据耗尽与再配比" aria-label="Permalink to &quot;数据耗尽与再配比&quot;">​</a></h1><div class="epigraph"><p>token 数要分两个账本：名义上喂了多少，和其中有多少是真正没见过的；耗尽发生在第二个账本上。</p><footer>—— 据 Muennighoff et al., Scaling Data-Constrained Language Models, 2023 与 Hernandez et al., 2022 整理</footer></div><p><a href="/llm/pf2-midtrain-eval-gates">上一课</a>把中途决策收进门禁，其中「调整」通道的合法入口之一就是数据侧的再配比。本课写这条通道本身：训练中途发现数据不够，怎么判、怎么补、怎么记账。<a href="/llm/data-constrained-scaling">数据受限缩放</a>与<a href="/llm/multi-epoch-repetition">多 epoch 重复</a>已经给出规律；本课把它们接到配方决策：耗尽的判定信号、补救选项的次序、以及被迫重复与有意过训的区分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>耗尽的判定之所以容易错，是因为名义 token 数永远好看：配比定稿时每个桶都写足了量，但清洗与去重之后<strong>独特数据</strong> \\(U\\) 往往比计划少一截，而训练日志上的 \\(D\\) 名义值照常增长。用名义 \\(D\\) 规划的团队会在后段不知不觉进入高重复率体制：损失下降变缓、记忆回路被强化、验证集若与训练池有重叠还会先涨后骗。判定要用<a href="/llm/data-constrained-scaling">有效数据</a> \\(D&#39;\\) 而不是名义 \\(D\\)：重复的边际收益在头几个 epoch 后快速衰减，之后每个名义 token 换来的新信息越来越少。</p><p><span class="marginnote">「独特数据」\\(U\\) 就是清洗去重后真正「没见过」的 token 量：100B 名义 token 里若混进大量重复网页，去重后可能只剩 60B 算数。规划弹药要按 \\(U\\) 算，不按日志上好看的 \\(D\\) 算。</span></p><h3 id="判定与补救次序" tabindex="-1">判定与补救次序 <a class="header-anchor" href="#判定与补救次序" aria-label="Permalink to &quot;判定与补救次序&quot;">​</a></h3><p>判定信号三条：桶级台账显示剩余独特 token 低于计划消耗；重复记账表显示有效 epoch 数进入衰减区；曲线对照同桶的历史 epoch 表现。补救按代价排序。<strong>先扩独特源</strong>：新来源、许可解锁、<a href="/llm/synthetic-pretrain">合成补丁</a>——合成在预训练里是补真实数据的稀疏，不是主食。<strong>再调重复率</strong>：头几轮重复接近新数据，把它当扩 \\(D&#39;\\) 的手段用满，但记进重复账本。<strong>最后动规模</strong>：改 \\(N\\) 等于改配方的一切坐标——超参、日程、检查点都要重对，中途改 \\(N\\) 是最重的选项，通常留给下一次点火。</p>',8)),(e(),n(l,null,{default:E(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A1%B6%E7%BA%A7%E5%8F%B0%E8%B4%A6%20%2B%20%E9%87%8D%E5%A4%8D%E8%AE%B0%E8%B4%A6%22%5D%20--%3E%20B%7B%22D'%20%E6%94%AF%E6%92%91%E5%BE%97%E5%88%B0%E7%BB%88%E7%82%B9%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20GO%5B%22%E6%8C%89%E5%8E%9F%E8%AE%A1%E5%88%92%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20C%5B%22%E6%89%A9%E7%8B%AC%E7%89%B9%E6%BA%90%EF%BC%9A%E6%96%B0%E6%BA%90%20%2F%20%E8%AE%B8%E5%8F%AF%20%2F%20%E5%90%88%E6%88%90%E8%A1%A5%E4%B8%81%22%5D%0A%20%20C%20--%3E%20D%7B%22%E5%A4%9F%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20E%5B%22%E7%94%A8%E6%BB%A1%E4%BD%8E%E9%87%8D%E5%A4%8D%E5%8C%BA%E9%97%B4%E5%B9%B6%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20E%20--%3E%20F%7B%22%E5%A4%9F%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20G%5B%22%E6%98%BE%E5%BC%8F%E9%99%8D%E7%9B%AE%E6%A0%87%E6%88%96%E6%94%B9%20N%20%E8%B5%B0%E5%8D%87%E7%89%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账口径三条。第一，<strong>两个账本并记</strong>：名义 \\(D\\) 与有效 \\(D&#39;\\) 分列，重复率 \\(R=D/U\\) 按桶记账；「无意重复」（去重漏网的）与「有意 epoch」都计入 \\(R\\)，否则 \\(D&#39;\\) 高估。第二，<strong>验证集有独立预算</strong>：验证集的重复上限单独设，且评测集重叠有<a href="/llm/eval-contamination">去污</a>审计——重复最容易先把验证集学好。第三，<strong>再配比走升版</strong>：中途把某桶权重调高（比如数学）是配比变更，按<a href="/llm/pf2-data-mix-final">配比定稿</a>的例外通道处理：声明变更理由、跑对照探针、升版本号；借「数据不够」之名把新桶混进来而不留档，是配比证据链断裂的开始。</p><p><span class="marginnote">衰减点会移动：大约前四个 epoch 的重复仍接近新数据，是特定容量与数据多样性下的拟合读数；小模型或窄分布上这个数会变。把「4」写进自动化脚本当常数，是本课最常见的事故。</span></p><p><span class="marginnote">数字实例：若某桶独特数据 \\(U=200B\\)、计划训 \\(D=800B\\)，重复率 \\(R=D/U=4\\)，等于名义上过 4 遍；按引用的读数，头几遍接近新数据，之后的每一轮收益都明显缩水——账面上 800B，有效的可能远少于此。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么补救次序按代价排：扩独特源改变 \\(U\\)，直接修复缺口，代价是采集与清洗时间；调重复率不改变 \\(U\\)，用衰减中的收益换 token 效率，代价随 \\(R\\) 上升——包括记忆化带来的隐私与泛化风险；改 \\(N\\) 动的是整个缩放坐标系，代价最大。这个次序与<a href="/llm/data-constrained-scaling">数据受限缩放</a>的结论一致：\\(D&#39;\\) 饱和后，增量算力更该花在加独特源或调 \\(N\\) 上，而不是无限重复。为什么被迫重复与过训要区分：过训是数据充足时<strong>故意</strong>拉大 \\(D/N\\) 换推理效率，重复体制清楚、目的明确；被迫重复是规划失误的事后状态，若不显式记账，事后分析会把两者混为一谈，把「规划失误」误读成「过训策略」。</p><p><span class="marginnote">直觉类比：同一道题做第二遍能巩固，做到第五遍基本只是在背答案——重复数据同理，头几轮在「学」，后面更多在「背」，背下来的东西换个问法就答不上来了。</span></p>',7)),(e(),n(l,null,{default:E(()=>[r(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8C%E6%A0%B7%E5%87%BA%E7%8E%B0%E9%AB%98%E9%87%8D%E5%A4%8D%E7%8E%87%EF%BC%9A%E4%BB%8E%E5%93%AA%E6%9D%A5%EF%BC%9F%22%5D%20--%3E%20B%5B%22%E8%A2%AB%E8%BF%AB%E9%87%8D%E5%A4%8D%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%9C%89%E6%84%8F%E8%BF%87%E8%AE%AD%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E8%A7%84%E5%88%92%E5%A4%B1%E8%AF%AF%EF%BC%9AU%20%E6%92%91%E4%B8%8D%E8%B5%B7%E8%AE%A1%E5%88%92%20D%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E9%87%8D%E5%A4%8D%E4%BD%93%E5%88%B6%E6%B7%B7%E8%B4%A6%EF%BC%9A%E6%97%A0%E6%84%8F%E6%BC%8F%E9%87%8D%E4%B8%8E%E8%A2%AB%E8%BF%AB%20epoch%20%E6%B7%B7%E5%9C%A8%E4%B8%80%E8%B5%B7%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E4%BA%8B%E5%90%8E%E6%98%93%E8%A2%AB%E8%AF%AF%E8%AF%BB%E6%88%90%E7%AD%96%E7%95%A5%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E6%95%B0%E6%8D%AE%E5%85%85%E8%B6%B3%EF%BC%9A%E6%95%85%E6%84%8F%E6%8B%89%E5%A4%A7%20D%2FN%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E9%87%8D%E5%A4%8D%E4%BD%93%E5%88%B6%E6%B8%85%E6%A5%9A%EF%BC%9A%E8%BD%AE%E6%95%B0%E4%B8%8E%E8%8C%83%E5%9B%B4%E5%85%A8%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E6%8D%A2%E6%9D%A5%E6%8E%A8%E7%90%86%E4%BE%A7%E7%9C%81%E5%8D%A1%EF%BC%8C%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张图回答的是「同一个高重复率表象，怎么分辨两种成因」：区分的抓手不在重复率数值本身，而在重复是否有意、是否可审计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管训练中段的数据缺口决策，不管数据管线怎么建——去重参数、指纹、预取是<a href="/llm/dataloader-pipeline">数据工程</a>与<a href="/llm/web-clean-dedup">网页清洗</a>的口径。合成补丁的具体工艺（改写、题解、回译）与崩塌风险的控制见<a href="/llm/synthetic-pretrain">合成数据在预训练</a>。退火期换高质量混合是<strong>计划内</strong>的配比切换，不是本课的应急再配比，两者在退火一课区分。课程学习式的顺序调整与配比无关，见<a href="/llm/data-ordering-curriculum">数据顺序与课程</a>。最后，若判定的结论是「\\(U\\) 永远撑不起这个 \\(N\\)」，正确的动作是把降目标提案交给下一次点火，而不是在本轮硬撑到死线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>耗尽判在有效数据 \\(D&#39;\\) 上：名义 \\(D\\) 好看不代表独特数据够用。</li><li>补救按代价排序：扩独特源、用满低重复区间并记账、最后才考虑改 \\(N\\)。</li><li>双账本并记：\\(D\\) 与 \\(D&#39;\\) 分列，重复率按桶记账，无意重复也算。</li><li>被迫重复与有意过训必须分开记账与叙述；再配比走显式升版。</li><li>出处：Muennighoff et al., 2023；Hernandez et al., 2022；合成占比约束见 DoReMi 与 RefinedWeb / FineWeb 的数据工作。</li></ul>',5))])}const _=o(D,[["render",d]]);export{F as __pageData,_ as default};
